#define max(a,b) ((a)>(b)?(a):(b))
int lcs(char* s1, char* s2) {
    int m=strlen(s1), n=strlen(s2), dp[m+1][n+1];
    for (int i=0; i<=m; i++) for (int j=0; j<=n; j++) dp[i][j]=i==0||j==0?0:s1[i-1]==s2[j-1]?dp[i-1][j-1]+1:max(dp[i-1][j], dp[i][j-1]);
    return dp[m][n];
}
